# Parameters
jobs = [1, 2, 3]
machines = [1, 2]
proces_time = [[1, 3], [2, 2], [3, 1]]  # rows: jobs, columns: machines

# Create model with provided environment
model = gp.Model(env=env)

# Decision variables
# y[i,j] = 1 if job i precedes job j in the sequence (i < j)
y = {}
for i in jobs:
    for j in jobs:
        if i < j:
            y[i, j] = model.addVar(vtype=GRB.BINARY, name=f"y_{i}_{j}")

# Start times S[i,m]
S = {}
for i in jobs:
    for m in machines:
        S[i, m] = model.addVar(vtype=GRB.CONTINUOUS, name=f"S_{i}_{m}")

# Makespan variable
Cmax = model.addVar(vtype=GRB.CONTINUOUS, name="Cmax")

# Big M for sequencing constraints
M_big = 100

# Constraints
