        for k in jobs:
            if i < j < k:
                model.addConstr(y[i, j] + y[j, k] + y[k, i] <= 2,
                                name=f"no_cycle_{i}_{j}_{k}")

# 3. Start times on first machine
for i in jobs:
    model.addConstr(S[i, 1] >= 0, name=f"start_first_{i}")

# 4. Sequential processing on each job
for i in jobs:
    for m in machines[1:]:
        model.addConstr(S[i, m] >= S[i, m - 1] + proces_time[i - 1][m - 2],
                        name=f"job_seq_{i}_{m}")

# 5. Machine sequencing constraints
for i in jobs:
    for j in jobs:
        if i != j:
            for m in machines:
                model.addConstr(
                    S[i, m] >= S[j, m] + proces_time[j - 1][m - 1] - M_big * (1 - y[i, j]),
                    name=f"machine_seq_{i}_{j}_{m}"
                )

# 6. Makespan constraints
for i in jobs:
    model.addConstr(Cmax >= S[i, machines[-1]] + proces_time[i - 1][machines[-1] - 1],
                    name=f"makespan_{i}")

# Objective: minimize makespan
model.setObjective(Cmax, GRB.MINIMIZE)

# Optimize
model.optimize()

# Output the final objective value
if model.status == GRB.OPTIMAL:
    obj_val = model.ObjVal
    # Print as integer if close to an integer
    if abs(round(obj_val) - obj_val) < 1e-6:
        obj_val = int(round(obj_val))
    print(f"FINAL_OBJECTIVE={obj_val}")
