import gurobipy as gp
from gurobipy import GRB

# Parameters
participants = ["P1", "P2", "P3"]
cars = ["C1", "C2", "C3"]
possible_assignments = [
    [1, 0, 1],  # P1 can take C1 or C3
    [0, 1, 0],  # P2 can take C2
    [1, 1, 1]   # P3 can take any car
]

model = gp.Model(env=env)

# Decision variables: x[i][j] = 1 if participant i assigned to car j
x = {}
for i, p in enumerate(participants):
    for j, c in enumerate(cars):
        var_name = f"x_{p}_{c}"
        x[i, j] = model.addVar(vtype=GRB.BINARY, name=var_name)

# Constraints
# Each participant assigned to at most one car
for i, p in enumerate(participants):
    model.addConstr(
        gp.quicksum(x[i, j] for j in range(len(cars))) <= 1,
        name=f"participant_{p}_max_one_car"
    )

# Each car assigned to at most one participant
for j, c in enumerate(cars):
    model.addConstr(
        gp.quicksum(x[i, j] for i in range(len(participants))) <= 1,
        name=f"car_{c}_max_one_participant"
    )

# Respect possible assignments
for i in range(len(participants)):
    for j in range(len(cars)):
        if possible_assignments[i][j] == 0:
            model.addConstr(x[i, j] == 0, name=f"impossible_{i}_{j}")

# Objective: maximize total assignments
model.setObjective(
    gp.quicksum(x[i, j] for i in range(len(participants)) for j in range(len(cars))),
    GRB.MAXIMIZE
)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
